import React, { useState } from 'react'
import { useToast } from '@/components/ui/use-toast'
import { useStudySite } from '@/contexts/StudySiteContext'
import sitePackageService from '@/modules/site-packages/services/sitePackageService'

import SitePackageListPage from './components/SitePackageListPage'
import CreateSitePackageForm from './components/CreateSitePackageForm'

type Mode = 'list' | 'create'

const isDraftStatus = (status: unknown) =>
  String(status || 'Draft').trim().toLowerCase() === 'draft'

function studyIdFromPackage(pkg: any): string | null {
  const s = pkg?.study
  if (s && typeof s === 'object') {
    return (
      String(s._id || s.id || '').trim() ||
      String(s.studyId || '').trim() ||
      null
    )
  }
  if (typeof s === 'string' && s.trim()) return s.trim()
  return null
}

/** Prefer `siteId` (external code) to match Navbar site dropdown; fall back to UUID. */
function siteIdFromPackage(pkg: any): string | null {
  const x = pkg?.site
  if (x && typeof x === 'object') {
    return (
      String(x.siteId || '').trim() ||
      String(x._id || x.id || '').trim() ||
      null
    )
  }
  if (typeof x === 'string' && x.trim()) return x.trim()
  return null
}

const SitePackagesPage: React.FC = () => {
  const { toast } = useToast()
  const { selectedStudyId, selectedSiteId } = useStudySite()

  const [mode, setMode] = useState<Mode>('list')
  const [editingPackageId, setEditingPackageId] = useState<string | null>(null)
  const [packageContextOverride, setPackageContextOverride] = useState<{
    studyId: string | null
    siteId: string | null
  } | null>(null)

  const effectiveStudyId = packageContextOverride?.studyId ?? selectedStudyId
  const effectiveSiteId = packageContextOverride?.siteId ?? selectedSiteId

  const handleCreateNew = async () => {
    if (!selectedStudyId) {
      toast({
        title: 'Select a study first',
        description: 'Site Packages require an active study in the workspace.',
        variant: 'destructive',
      })
      return
    }
    if (!selectedSiteId) {
      toast({
        title: 'Select a site first',
        description: 'Site Packages are scoped to the current site and study.',
        variant: 'destructive',
      })
      return
    }
    setEditingPackageId(null)
    setPackageContextOverride(null)
    setMode('create')
  }

  const handleSelectPackage = (pkg: any) => {
    if (!pkg) return
    if (!isDraftStatus(pkg?.status)) {
      toast({
        title: 'Cannot open package',
        description: 'Only Draft site packages can be opened for editing.',
        variant: 'destructive',
      })
      return
    }
    const sid = studyIdFromPackage(pkg)
    const siteId = siteIdFromPackage(pkg) || selectedSiteId || null
    if (!sid) {
      toast({
        title: 'Cannot open package',
        description: 'This package has no study reference.',
        variant: 'destructive',
      })
      return
    }
    if (!siteId) {
      toast({
        title: 'Select a site first',
        description:
          'This package has no saved site. Choose a site in the dashboard header so IRB requirements can load.',
        variant: 'destructive',
      })
      return
    }
    setPackageContextOverride({ studyId: sid, siteId })
    setEditingPackageId(String(pkg._id || pkg.id || ''))
    setMode('create')
  }

  const handleFormExit = () => {
    setEditingPackageId(null)
    setPackageContextOverride(null)
    setMode('list')
  }

  return mode === 'list' ? (
    <SitePackageListPage
      selectedStudy={selectedStudyId}
      selectedSite={selectedSiteId}
      onCreateNew={handleCreateNew}
      onSelectPackage={handleSelectPackage}
    />
  ) : (
    <CreateSitePackageForm
      key={editingPackageId || 'new'}
      onSubmit={(payload: any) => sitePackageService.createSitePackage(payload)}
      onCancel={handleFormExit}
      onSuccess={handleFormExit}
      initialStudyId={(effectiveStudyId || null) as any}
      initialSiteId={(effectiveSiteId || null) as any}
      existingPackageId={editingPackageId as any}
    />
  )
}

export default SitePackagesPage
